using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class TestFarmTraversal {
 public static string Main(){if(!Application.isPlaying)throw new Exception("Play mode required");var root=GameObject.Find("New_Map").transform;var terrain=root.GetComponentInChildren<Terrain>();var report=new List<string>();int pass=0,fail=0;Action<bool,string> check=(ok,s)=>{report.Add((ok?"PASS ":"FAIL ")+s);if(ok)pass++;else fail++;};var g=new GameObject("Temporary validation walker");var cc=g.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.3f;cc.center=new Vector3(0,.9f,0);cc.skinWidth=.025f;
 try{foreach(var h in root.Find("11_Five_Hangar_Farm").Cast<Transform>().Where(t=>t.name.StartsWith("Hangar "))){cc.enabled=false;g.transform.position=h.TransformPoint(new Vector3(0,.12f,18));cc.enabled=true;Physics.SyncTransforms();cc.Move(-h.forward*10);check(h.InverseTransformPoint(g.transform.position).z>15.3f,h.name+" blocks CharacterController at locked door");}
 cc.enabled=false;g.transform.position=new Vector3(0,.15f,20);cc.enabled=true;cc.Move(Vector3.back*8);check(g.transform.position.z<13,"Starter hangar entrance remains open");
 foreach(var test in new[]{new[]{new Vector3(178,0,122),Vector3.right},new[]{new Vector3(-178,0,122),Vector3.left},new[]{new Vector3(0,0,-56),Vector3.back},new[]{new Vector3(0,0,300),Vector3.forward}}){var p=test[0];p.y=terrain.SampleHeight(p)+terrain.transform.position.y+.15f;cc.enabled=false;g.transform.position=p;cc.enabled=true;Physics.SyncTransforms();cc.Move(test[1]*10);check(Vector3.Dot(g.transform.position-p,test[1])<4,"Map perimeter stops CharacterController "+test[1]);}
 foreach(var pile in Object.FindObjectsByType<GrainPile>(FindObjectsSortMode.None)){pile.Initialize();check(pile.GetComponent<CornSurfaceKernels>().KernelCount>0,pile.name+" kernels initialized after scene load");var p=pile.transform.position;p.y=pile.SurfaceHeight(p);double before=pile.Kilograms;float kg=pile.Scoop(p,.45f,.12f,6.5f);check(kg>0&&Math.Abs(before-pile.Kilograms-kg)<.1,pile.name+" remains scoopable with conserved mass");}
 }finally{Object.DestroyImmediate(g);}string result=pass+" passed, "+fail+" failed\n"+string.Join("\n",report);File.WriteAllText("output/NewMap/FiveHangars/play-validation.txt",result);return result;
 }
}

